command:
set -eu
node /app/dist/index.js plugins install /openshell-plugin --force
config_root=/home/node/.openclaw/.config/openshell
gateway_name="mosaic-openshell"
gateway_endpoint="https://mosaic-openshell:8080"
metadata_path="$config_root/gateways/$gateway_name/metadata.json"
mkdir -p "$(dirname "$metadata_path")"
printf "%s" "$gateway_name" > "$config_root/active_gateway"
node - "$metadata_path" "$gateway_name" "$gateway_endpoint" <<'EOF'
const fs = require("fs");
const path = require("path");
const [metadataPath, name, endpoint] = process.argv.slice(2);
fs.mkdirSync(path.dirname(metadataPath), { recursive: true });
fs.writeFileSync(metadataPath, JSON.stringify({
  name,
  gateway_endpoint: endpoint,
  is_remote: false,
  gateway_port: 0,
  auth_mode: "mtls"
}, null, 2));
EOF
